(function(){"use strict";var _p=['33','651','311','169'];window._phone=_p.join('');function getWaMsg(){var el=document.querySelector('[data-phone-link="wa"]');return el?(el.getAttribute('data-wa-msg')||''):'';}
function getSmsMsg(){var el=document.querySelector('[data-phone-link="sms"]');return el?(el.getAttribute('data-sms-msg')||''):'';}
document.addEventListener('DOMContentLoaded',function(){var ph=window._phone;var display='+'+ph.substring(0,2)+' '+ph[2]+' '+ph.substring(3,5)+' '+ph.substring(5,7)+' '+ph.substring(7,9)+' '+ph.substring(9,11);document.querySelectorAll('[data-phone-link]').forEach(function(el){var type=el.getAttribute('data-phone-link');var waMsg=el.getAttribute('data-wa-msg')||'';var smsMsg=el.getAttribute('data-sms-msg')||'';if(type==='tel'){el.href='tel:+'+ph;}else if(type==='wa'){el.href='https://wa.me/'+ph+(waMsg?'?text='+waMsg:'');}else if(type==='sms'){el.href='sms:+'+ph+(smsMsg?'&body='+smsMsg:'');}});document.querySelectorAll('.phone-display').forEach(function(el){el.textContent=display;});});document.querySelectorAll('a[href^="#"]').forEach(function(link){link.addEventListener("click",function(e){var targetId=this.getAttribute("href");if(targetId==="#")return;var target=document.querySelector(targetId);if(!target)return;e.preventDefault();var offset=target.getBoundingClientRect().top+window.scrollY-70;window.scrollTo({top:offset,behavior:"smooth"});});});var navCollapse=document.getElementById("navbarNav");if(navCollapse){navCollapse.querySelectorAll(".nav-link:not(.dropdown-toggle)").forEach(function(link){link.addEventListener("click",function(){var bsCollapse=bootstrap.Collapse.getInstance(navCollapse);if(bsCollapse)bsCollapse.hide();});});navCollapse.querySelectorAll("#langSwitcher .dropdown-item").forEach(function(item){item.addEventListener("click",function(){var bsCollapse=bootstrap.Collapse.getInstance(navCollapse);if(bsCollapse)bsCollapse.hide();});});}
var navbar=document.getElementById("mainNav");function updateNavbar(){if(window.scrollY>100){navbar.classList.add("navbar-scrolled");navbar.classList.remove("navbar-dark");navbar.classList.add("navbar-light");}else{navbar.classList.remove("navbar-scrolled");navbar.classList.add("navbar-dark");navbar.classList.remove("navbar-light");}}
window.addEventListener("scroll",updateNavbar,{passive:true});updateNavbar();var backToTop=document.getElementById('backToTop');if(backToTop){window.addEventListener('scroll',function(){backToTop.classList.toggle('visible',window.scrollY>400);},{passive:true});}
var animatedElements=document.querySelectorAll(".animate-on-scroll");if(animatedElements.length>0&&"IntersectionObserver"in window){var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add("animated");observer.unobserve(entry.target);}});},{threshold:0.1});animatedElements.forEach(function(el){observer.observe(el);});}
document.querySelectorAll('.share-copy-link').forEach(function(link){link.addEventListener('click',function(e){e.preventDefault();var url=this.getAttribute('data-url');navigator.clipboard.writeText(url).then(function(){var icon=link.querySelector('i');icon.className='bi bi-check-lg';var tooltip=document.createElement('span');tooltip.className='copy-tooltip';tooltip.textContent=link.getAttribute('data-copied')||'Copié !';link.appendChild(tooltip);setTimeout(function(){icon.className='bi bi-link-45deg';if(tooltip.parentNode)tooltip.parentNode.removeChild(tooltip);},2000);});});});document.querySelectorAll('link.async-css').forEach(function(link){if(link.sheet){link.media='all';}else{link.addEventListener('load',function(){this.media='all';});}});document.addEventListener('click',function(e){var toggle=e.target.closest('.review-toggle');if(!toggle)return;e.preventDefault();var card=toggle.closest('.review-card');var translated=card.querySelector('.review-translated');var original=card.querySelector('.review-original');var showing=original.style.display!=='none';translated.style.display=showing?'':'none';original.style.display=showing?'none':'';});document.addEventListener('click',function(e){var link=e.target.closest('.obfuscated-email');if(!link)return;var u=link.getAttribute('data-eu');var d=link.getAttribute('data-ed');if(!u||!d)return;var addr=atob(u)+'@'+atob(d);var subject=link.getAttribute('data-es')||'';var body=link.getAttribute('data-eb')||'';link.href='mailto:'+addr+'?subject='+subject+'&body='+body;});var btnShow=document.getElementById('btnShowReviews');if(btnShow){btnShow.addEventListener('click',function(){var items=document.querySelectorAll('.review-extra');for(var i=0;i<items.length;i++)items[i].classList.remove('review-extra');this.style.display='none';});}
function updateStickyOffsets(){var vh=window.innerHeight;document.querySelectorAll('main#main > section').forEach(function(s){var h=s.offsetHeight;s.style.top=(h>vh)?(vh-h)+'px':'0px';});var footer=document.querySelector('footer.bg-dark');if(footer){var fh=footer.offsetHeight;footer.style.top=(fh>vh)?(vh-fh)+'px':'0px';}}
window.addEventListener('load',updateStickyOffsets);window.addEventListener('resize',updateStickyOffsets);})();document.addEventListener('click',function(e){var link=e.target.closest('a');if(!link||!window.dataLayer)return;var href=link.getAttribute('href')||'';var event=null;if(href.indexOf('wa.me')!==-1)event='click_whatsapp';else if(href.indexOf('sms:')===0)event='click_sms';else if(href.indexOf('tel:')===0)event='click_phone';else if(href.indexOf('mailto:')===0)event='click_email';if(!event)return;var section='other';if(link.classList.contains('whatsapp-float')||link.classList.contains('imessage-float'))section='float';else if(link.closest('#tarifsContainer'))section='tarifs_table';else if(link.closest('.tarifs-contact-links'))section='tarifs_contact';else if(link.closest('#contact'))section='contact';else if(link.closest('#tarifs'))section='tarifs';else if(link.closest('header'))section='share';window.dataLayer.push({event:event,link_url:href,click_section:section});});